-- Split loyalty read access from mutation authority. Analysts are read-only.
create or replace function public.can_read_loyalty(p_instance_id uuid,p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$select public.is_platform_operator(p_user_id) or public.has_store_role(p_instance_id,array['owner','admin','marketing_manager','analyst'],p_user_id);$$;
create or replace function public.can_manage_loyalty(p_instance_id uuid,p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$select public.is_platform_operator(p_user_id) or public.has_store_role(p_instance_id,array['owner','admin','marketing_manager'],p_user_id);$$;
do $$declare p record;t text;begin foreach t in array array['customer_value_profiles','loyalty_benefit_rules','loyalty_benefit_usage','loyalty_ledger','loyalty_processing_runs','loyalty_program_settings'] loop for p in select policyname from pg_policies where schemaname='public' and tablename=t loop execute format('drop policy if exists %I on public.%I',p.policyname,t);end loop;execute format('create policy %I on public.%I for select to authenticated using(public.can_read_loyalty(instance_id))',t||'_tenant_read',t);execute format('create policy %I on public.%I for insert to authenticated with check(public.can_manage_loyalty(instance_id))',t||'_tenant_insert',t);execute format('create policy %I on public.%I for update to authenticated using(public.can_manage_loyalty(instance_id)) with check(public.can_manage_loyalty(instance_id))',t||'_tenant_update',t);execute format('create policy %I on public.%I for delete to authenticated using(public.can_manage_loyalty(instance_id))',t||'_tenant_delete',t);end loop;end$$;
-- Tenant-safe RPCs are application/service entry points only.
do $$declare r record;begin for r in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['refresh_customer_value_profiles_v2','accrue_loyalty_points_from_paid_orders_v2','get_customer_loyalty_snapshot_v2']) loop execute format('revoke execute on function %s from public, anon, authenticated',r.sig);execute format('grant execute on function %s to service_role',r.sig);end loop;end$$;
